#include "oa_native_ao.h"
#include "oa_native_ao_math.h"
#include "native_ao_shaders.h"
#include <stdlib.h>
#include <string.h>
extern GLuint oa_post_program(const char *,const char *);
static const char *vertex="#version 300 es\nvoid main(){vec2 p=vec2(float((gl_VertexID<<1)&2),float(gl_VertexID&2));gl_Position=vec4(p*2.-1.,0.,1.);}";
/* Native near-AO/fullwhite complementary depth-tested draws are represented
 * by a gate AFTER all derivative calculations. No depth texture is attached
 * while being sampled, avoiding an OpenGL framebuffer feedback loop. */
static GLuint gate_program(const char *src){const char *main_fn=strstr(src,"void main()");const char *rename="void oa_ao_compute()";const char *end="\nuniform highp sampler2D gate_depth;uniform float gate_cut;void main(){oa_ao_compute();if(texture(gate_depth,gl_FragCoord.xy/nativeExtent).r>=gate_cut)o=vec4(1.);}\n";size_t a,b,c;char *shader;GLuint result;if(!main_fn)return 0;a=(size_t)(main_fn-src);b=strlen(main_fn+11);c=a+strlen(rename)+b+strlen(end)+1;shader=(char*)malloc(c);if(!shader)return 0;memcpy(shader,src,a);memcpy(shader+a,rename,strlen(rename));memcpy(shader+a+strlen(rename),main_fn+11,b);memcpy(shader+a+strlen(rename)+b,end,strlen(end)+1);result=oa_post_program(vertex,shader);free(shader);return result;}
void oa_native_ao_close(oa_native_ao *p){glDeleteTextures(3,p->tex);glDeleteFramebuffers(3,p->fbo);if(p->ao)glDeleteProgram(p->ao);if(p->blur)glDeleteProgram(p->blur);if(p->vao)glDeleteVertexArrays(1,&p->vao);memset(p,0,sizeof(*p));}
int oa_native_ao_open(oa_native_ao *p,int w,int h){int i;memset(p,0,sizeof(*p));if(w<=0||h<=0)return 0;p->w=w;p->h=h;p->ao=gate_program(oa_native_ao_fs);p->blur=gate_program(oa_native_ao_bilateral_fs);if(!p->ao||!p->blur)goto fail;glGenVertexArrays(1,&p->vao);glGenTextures(3,p->tex);glGenFramebuffers(3,p->fbo);for(i=0;i<3;i++){glBindTexture(GL_TEXTURE_2D,p->tex[i]);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,0);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glBindFramebuffer(GL_FRAMEBUFFER,p->fbo[i]);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,p->tex[i],0);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)goto fail;}glBindFramebuffer(GL_FRAMEBUFFER,0);p->ready=glGetError()==GL_NO_ERROR;if(p->ready)return 1;fail:oa_native_ao_close(p);glBindFramebuffer(GL_FRAMEBUFFER,0);return 0;}
static void pass(oa_native_ao *p,int i,GLuint source,GLuint depth,const float c[32],float cut){GLuint prog=i?p->blur:p->ao;glBindFramebuffer(GL_FRAMEBUFFER,p->fbo[i]);glViewport(0,0,p->w,p->h);glUseProgram(prog);glUniform4fv(glGetUniformLocation(prog,"c[0]"),i?1:6,c);glUniform2f(glGetUniformLocation(prog,"nativeExtent"),(float)p->w,(float)p->h);glUniform4f(glGetUniformLocation(prog,"passthrough"),i==1?1.f:0.f,i==1?0.f:1.f,i==1?0.f:1.f,i==1?0.f:1.f);glUniform1f(glGetUniformLocation(prog,"gate_cut"),cut);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,source);glUniform1i(glGetUniformLocation(prog,"src"),0);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_2D,depth);glUniform1i(glGetUniformLocation(prog,"gate_depth"),1);glDrawArrays(GL_TRIANGLES,0,3);}
GLuint oa_native_ao_render_constants(oa_native_ao *p,GLuint depth,const float block[32],float cut){float c[32];if(!p->ready||!depth||!block||!isfinite(cut))return 0;glDisable(GL_DEPTH_TEST);glDisable(GL_BLEND);glDisable(GL_CULL_FACE);glDisable(GL_SCISSOR_TEST);glDisable(GL_DITHER);glBindVertexArray(p->vao);pass(p,0,depth,depth,block,cut);memcpy(c,block,sizeof(c));c[0]=3.f/p->w;c[1]=0;c[2]=35;pass(p,1,p->tex[0],depth,c,cut);c[0]=0;c[1]=3.f/p->h;pass(p,2,p->tex[1],depth,c,cut);return p->tex[2];}
GLuint oa_native_ao_render(oa_native_ao *p,GLuint depth,const float gl_vp[16]){float c[32],cut;if(!p||!p->ready||!oa_native_ao_parameters(c,&cut,gl_vp,p->w,p->h))return 0;return oa_native_ao_render_constants(p,depth,c,cut);}
